with recent_subscriptions as (select *, datediff(current_date(), start_date) days_since_start_date from subscriptions where plan = 'enterprise' or start_date >= '2024-11-01'), subscriptions_stats as (select status, round(stddev(days_since_start_date), 2) stddev_days_since_start_date, round(avg(monthly_fee), 2) avg_monthly_fee from recent_subscriptions group by status) select status, stddev_days_since_start_date, avg_monthly_fee from subscriptions_stats
